function isoForDay(day){const d=new Date(`${START_DATE}T12:00:00Z`);d.setUTCDate(d.getUTCDate()+day);return d.toISOString().slice(0,10);}
export function formatGameDate(game){return new Intl.DateTimeFormat('es-ES',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(`${game.calendarISO}T12:00:00Z`));}
function uid(prefix,game,extra=''){return `${prefix}-${game.day}-${hashString(`${extra}-${game.day}-${game.week}-${game.club.id}-${game.inbox?.length||0}`)%999999}`;}
function mail(game,{sender='Secretaría del club',subject,body,tone='info',screen=null,entityId=null}){
  const item={id:uid('mail',game,subject),day:game.day,date:game.calendarISO,sender,subject,body,tone,screen,entityId,unread:true};
  return {...game,inbox:[item,...(game.inbox||[])].slice(0,120)};
}
export function markMailRead(game,id){return {...game,inbox:game.inbox.map(m=>m.id===id?{...m,unread:false}:m)};}
export function unreadMail(game){return (game.inbox||[]).filter(x=>x.unread).length;}

function randomInitialLevel(club,group,id){
  if(id==='capacity'||id==='roof'||id==='standHeating')return 0;
  const r=rng(hashString(`${club.id}-${group}-${id}-initial-v43`))(),strength=clamp((club.prestige-42)/28,0,1);
  const chance=group==='stadium'?.48+strength*.18:group==='sport'?.34+strength*.16:.30+strength*.14;
  return r<chance?1:0;
}
function buildInitialLevels(club){
  const out={stadium:{},club:{},sport:{}};
  for(const group of Object.keys(out))for(const id of Object.keys(facilityDefs[group]))out[group][id]=randomInitialLevel(club,group,id);
  return out;
}
function cumulativeEffect(group,id,level,key){let v=0;for(let i=1;i<=level;i++)v+=Number(facilityDefs[group]?.[id]?.levels?.[i]?.effects?.[key]||0);return v;}
function kitPreferences(club){const palette=['#8b1e2d','#1f4f9a','#f2f2f2','#111827','#e8c547','#287a5b','#6b3fa0','#f07d2b'];const r=rng(hashString(`${club.id}-kit-pref`));return {primary:palette[Math.floor(r()*palette.length)],secondary:palette[Math.floor(r()*palette.length)],style:kitStyles[Math.floor(r()*kitStyles.length)],tradition:55+Math.floor(r()*36)};}
function ensureStats(p){return {...p,nationality:p.nationality||['España','Portugal','Argentina','Uruguay','Francia','Marruecos','Colombia'][hashString(p.name)%7],stats:p.stats||{apps:0,starts:0,minutes:0,goals:0,assists:0,yellow:0,ratingSum:0}};}

