  const prefs=kitPreferences(club);const kit={preferences:prefs,primary:prefs.primary,secondary:prefs.secondary==prefs.primary?'#ffffff':prefs.secondary,accent:'#ffffff',style:prefs.style,collar:'Redondo',sleeve:'Borde de manga',manufacturer:null,manufacturerOffers:[],manufacturerSearch:null,appeal:76,history:[]};
  g={...g,version:4,day:0,calendarISO:START_DATE,dateLabel:formatGameDate({calendarISO:START_DATE}),players:g.players.map(ensureStats),market:g.market.map(ensureStats),infrastructure:{...g.infrastructure,levels,projects:[],maxProjects:3},stadium:{...g.stadium,commercialSlots,condition:76},sponsorOffers:[],activeSponsorRights:[],sponsorSearches:{},sponsorNegotiations:{},staffPositions:['Entrenador'],staffSearches:{},staffCandidatePools:{},staffNegotiations:{},coachRecommendations:{},transferNegotiations:{},processes:[],kit,
    mediaProgram:{autographs:'important',channels:{instagram:true,x:true,tiktok:false,youtube:false},postsPerWeek:4,tone:'Cercano',programme:false,magazine:false,radio:false,tv:false},
    events:[],financeV4:{debt:0,debtRate:0,investments:[],investmentProfit:0,capitalContributions:0},boardV4:{requests:[],objectiveNegotiations:{}},trainingPlan:{intensity:'balanced',focus:'balanced',restDays:1},controlMode:'coach',matchReady:false};
  g=mail(g,{sender:'Presidenta de la directiva',subject:'Bienvenido: tus primeros objetivos',body:`La directiva espera que profesionalices ${club.name} sin comprometer la caja. Puedes negociar objetivos, pedir capital y decidir qué áreas construir primero.`,screen:'board'});
  g=mail(g,{sender:'Secretaría deportiva',subject:'El calendario ya está disponible',body:'Tienes resultados, clasificación, calendario y estadísticas dentro de Deportivo → Resultados y competición.',screen:'competitions'});
