  if(stage==='club'){result=Base.evaluateClubOffer(game,player,amount,prev.round+1);nextState={...prev,stage:result.status==='accepted'?'player':'club',round:prev.round+1,status:result.status,counter:result.counter,lastAmount:amount,message:result.message};}
