export function takeControl(game){if(game.staff.coach)return game;return {...game,controlMode:'self'};}
export function appointInterim(game,key){if(game.staff.coach)return game;const person=game.staff[key];if(!person)return game;const coach={...person,id:`interim-${person.id}`,role:'Entrenador interino',salary:0,tactic:person.tactic||game.gmTactic,rating:Math.round((person.rating||55)*.88),interim:true,interimSource:key,ego:30,flexibility:80,reputation:Math.round((person.reputation||50)*.75)};return {...game,staff:{...game.staff,coach},controlMode:'coach',coachRelationship:{trust:78,respect:50,interventions:0,autonomy:'interim'}};}

export function submitClubOffer(game,playerId,amount){const n=game.transferNegotiations[playerId];if(n?.status==='waiting')return game;const process={id:uid('transfer-club',game,playerId),type:'transferNegotiation',dueDay:game.day+1,payload:{playerId,stage:'club',amount:Number(amount)}};return {...game,processes:[...game.processes,process],transferNegotiations:{...game.transferNegotiations,[playerId]:{...(n||{stage:'club',round:0,tension:0}),status:'waiting',lastAmount:Number(amount),message:'Oferta enviada al club. Responderán mañana.'}}};}
export function submitPlayerOffer(game,playerId,salary,signing){const n=game.transferNegotiations[playerId];if(n?.status==='waiting')return game;const process={id:uid('transfer-player',game,playerId),type:'transferNegotiation',dueDay:game.day+1,payload:{playerId,stage:'player',salary:Number(salary),signing:Number(signing)}};return {...game,processes:[...game.processes,process],transferNegotiations:{...game.transferNegotiations,[playerId]:{...(n||{stage:'player',round:0}),stage:'player',status:'waiting',lastSalary:Number(salary),lastSigning:Number(signing),message:'Oferta contractual enviada. Respuesta mañana.'}}};}
export function completeTransfer(game,playerId){const n=game.transferNegotiations[playerId],p=game.market.find(x=>x.id===playerId);if(!p||n?.stage!=='ready'||n.status!=='accepted')return game;const fee=p.club==='Libre'?0:(n.lastAmount||p.seller.asking);return Base.completeTransfer(game,p,fee,n.lastSalary,n.lastSigning);}

export function startManufacturerSearch(game,duration){if((game.processes||[]).some(p=>p.type==='manufacturerSearch'))return game;const process={id:uid('manufacturer',game),type:'manufacturerSearch',dueDay:game.day+duration,payload:{duration}};return {...game,processes:[...game.processes,process],kit:{...game.kit,manufacturerSearch:{status:'searching',duration,dueDay:process.dueDay},manufacturerOffers:[]}};}
export function signManufacturer(game,id){const m=game.kit.manufacturerOffers.find(x=>x.id===id);if(!m)return game;return {...game,kit:{...game.kit,manufacturer:m,manufacturerOffers:[]}};}
function colorMatch(a,b){return a.toLowerCase()===b.toLowerCase()?100:45;}
export function saveKitDesign(game,patch){const manufacturer=game.kit.manufacturer;if(manufacturer&&!manufacturer.colorControl&&(patch.primary||patch.secondary))patch={...patch,primary:game.kit.primary,secondary:game.kit.secondary};if(manufacturer&&!manufacturer.styleControl&&(patch.style||patch.sleeve||patch.collar))patch={...patch,style:game.kit.style,sleeve:game.kit.sleeve,collar:game.kit.collar};const nextKit={...game.kit,...patch};const p=nextKit.preferences;const tradition=(colorMatch(nextKit.primary,p.primary)*.5+colorMatch(nextKit.secondary,p.secondary)*.18+(nextKit.style===p.style?100:55)*.22+p.tradition*.1);const novelty=game.kit.history.length===0?4:nextKit.style!==game.kit.style?7:0;nextKit.appeal=clamp(Math.round(tradition*.78+22+novelty),35,98);return {...game,kit:nextKit};}

export function produceMerch(game,key,qty){qty=Math.floor(Number(qty));const base={shirt:17,scarf:6,cap:8}[key];if(!base||qty<=0)return game;const b=Base.facilityBonuses(game),pending=(game.processes||[]).filter(p=>p.type==='merchProduction').reduce((s,p)=>s+(p.payload.qty||0),0),inventory=Object.values(game.merch.inventory).reduce((a,x)=>a+x,0),cap=b.inventoryCap||800;if(inventory+pending+qty>cap)return mail(game,{sender:'Logística',subject:'Pedido de fabricación bloqueado',body:`No hay capacidad de almacén para este lote. Capacidad: ${cap.toLocaleString('es-ES')} uds contando pedidos pendientes.`,tone:'warning',screen:'merch'});const cmoDiscount=1-((game.staff.cmo?.rating??0)/1000),cost=Math.round(base*qty*cmoDiscount);if(game.cash<cost)return game;const days=clamp(2+Math.ceil(qty/550),3,28),process={id:uid('merch-prod',game,`${key}-${qty}`),type:'merchProduction',dueDay:game.day+days,payload:{key,qty,cost,days}};return {...game,cash:game.cash-cost,processes:[...game.processes,process],merch:{...game.merch,produced:{...game.merch.produced,[key]:(game.merch.produced[key]||0)+qty}},finance:{...game.finance,costs:game.finance.costs+cost}};}

export function setMediaProgram(game,patch){return {...game,mediaProgram:{...game.mediaProgram,...patch,channels:patch.channels?{...game.mediaProgram.channels,...patch.channels}:game.mediaProgram.channels}};}
export function scheduleEvent(game,type,dateISO){const d=eventCatalog[type];if(!d)return game;const target=Math.round((new Date(`${dateISO}T12:00:00Z`)-new Date(`${START_DATE}T12:00:00Z`))/DAY_MS);if(target<=game.day||target>game.day+240)return game;const deposit=Math.round(d.cost*.25);if(game.cash<deposit)return game;const event={id:uid('event',game,`${type}-${dateISO}`),type,day:target,dateISO,status:'scheduled',deposit};return {...game,cash:game.cash-deposit,events:[...game.events,event],finance:{...game.finance,costs:game.finance.costs+deposit}};}

export function signSupplier(game,category,candidate){const setup=candidate.setupFee||0;if(game.cash<setup)return game;let next=Base.signSupplier({...game,cash:game.cash-setup},category,candidate);next.finance={...next.finance,costs:next.finance.costs+setup};return next;}
export function startInvestment(game,type,amount,termDays=365){amount=Number(amount);if(amount<=0||game.cash<amount)return game;const inv={id:uid('investment',game,type),type,amount,termDays,startDay:game.day,dueDay:game.day+termDays,status:'active'};const process={id:`proc-${inv.id}`,type:'investment',dueDay:inv.dueDay,payload:{investmentId:inv.id}};return {...game,cash:game.cash-amount,financeV4:{...game.financeV4,investments:[...game.financeV4.investments,inv]},processes:[...game.processes,process]};}
export function takeDebt(game,amount){amount=Number(amount);if(amount<=0)return game;const cfo=game.staff.cfo?.rating||0;const rate=Math.max(.035,.065+debtRatio(game)*.055-cfo*.00018);const newRatio=(game.financeV4.debt+amount)/Math.max(1,annualRevenueEstimate(game));return {...game,cash:game.cash+amount,financeV4:{...game.financeV4,debt:game.financeV4.debt+amount,debtRate:rate},boardConfidence:clamp(game.boardConfidence-(newRatio>.5?4:1),0,100)};}
export function requestBoardCapital(game,amount){const process={id:uid('board-capital',game),type:'boardRequest',dueDay:game.day+3,payload:{kind:'capital',amount:Number(amount)}};return {...game,processes:[...game.processes,process]};}
export function requestObjectiveChange(game,objectiveId){const process={id:uid('board-objective',game,objectiveId),type:'boardRequest',dueDay:game.day+2,payload:{kind:'objective',objectiveId}};return {...game,processes:[...game.processes,process]};}

export function commissionFacilityProject(game,group,assetId,targetLevel){const current=game.infrastructure.levels[group]?.[assetId]||0,target=Number(targetLevel);if(target<=current||target>maxLevel(group,assetId))return game;if((game.processes||[]).some(p=>p.type==='facility'&&p.payload.group===group&&p.payload.assetId===assetId))return game;if((game.processes||[]).filter(p=>p.type==='facility').length>=game.infrastructure.maxProjects)return game;let cost=0,weeks=0;for(let i=current+1;i<=target;i++){const d=facilityDefs[group][assetId].levels[i];const req=d.requires||{};if(req.minCapacity&&game.stadium.capacity<req.minCapacity)return game;if(req.minBrand&&game.brandScore<req.minBrand)return game;cost+=d.cost;weeks+=d.weeks;}if(game.cash<cost)return game;const process={id:uid('facility',game,`${group}-${assetId}-${target}`),type:'facility',dueDay:game.day+weeks*7,payload:{group,assetId,targetLevel:target,startLevel:current,name:facilityDefs[group][assetId].levels[target].name,cost,weeks}};return {...game,cash:game.cash-cost,processes:[...game.processes,process],finance:{...game.finance,costs:game.finance.costs+cost,facilities:game.finance.facilities+cost}};}
export function activeFacilityProjects(game){return (game.processes||[]).filter(p=>p.type==='facility').map(p=>({...p.payload,id:p.id,dueDay:p.dueDay,remainingDays:p.dueDay-game.day}));}

export function setTrainingPlan(game,patch,force=false){if(game.staff.coach&&game.controlMode==='coach'&&!game.staff.coach.interim){const coach=game.staff.coach,rel=game.coachRelationship;const acceptance=clamp(30+game.gm.stats.tactics*2+rel.trust*.35+coach.flexibility*.3-coach.ego*.15,15,92);const roll=hashString(`${game.day}-${JSON.stringify(patch)}-${coach.id}`)%100;if(!force&&roll>acceptance)return mail(game,{sender:coach.name,subject:'Plan de entrenamiento rechazado',body:'El entrenador considera que cambiar la planificación esta semana perjudicaría su metodología.',tone:'warning',screen:'training'});const trust=clamp(rel.trust+(force?-6:1),0,100);return {...game,trainingPlan:{...game.trainingPlan,...patch},trainingIntensity:patch.intensity||game.trainingIntensity,coachRelationship:{...rel,trust}};}return {...game,trainingPlan:{...game.trainingPlan,...patch},trainingIntensity:patch.intensity||game.trainingIntensity};}
